    {
      "card_ids": ["C21"],
      "claim": "Melperone, a close butyrophenone analogue with the same Ar-CO-CH2CH2CH2-N basic amine chain, showed absolute oral bioavailability of 67 ± 28% in healthy volunteers, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Haloperidol, a butyrophenone antipsychotic with a basic piperidine moiety, has an absolute oral bioavailability of 60% in patients, supporting the high-F prediction for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Bromperidol, a close haloperidol-like butyrophenone, has a human oral bioavailability of 30%, still above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Ebastine, a butyrophenone-related basic amine drug, achieves about 40% oral bioavailability in humans, supporting the expectation that this scaffold is not limited to low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Raloxifene has very low absolute bioavailability (2%), but this is driven by phenolic glucuronidation and a scaffold very different from the query; it is contradictory only for that distant analogue and has low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the query is a butyrophenone-type tertiary amine with close analogues (melperone, haloperidol, bromperidol, ebastine) showing absolute oral bioavailability of 30-70%. Low-bioavailability analogues such as raloxifene are structurally distant and their low-F mechanisms do not apply to the query.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule.",
    "The effect of the 3,4,5-trimethoxyphenyl substitution on first-pass metabolism and absorption is not directly measured.",
    "Morgan similarity scores to the closest evidence molecules are modest, so extrapolation relies on chemical class analogy rather than high fingerprint similarity."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

